alter table public.cards enable row level security;

-- Grant service_role full access to all tables
grant all on public.boards to service_role;
grant all on public.board_members to service_role;
grant all on public.cards to service_role;

-- Allow service_role to manage the schema objects
grant usage on schema public to service_role;

-- ---------------------------------------------------------
-- POLICIES: boards
-- ---------------------------------------------------------

-- R6: Boards and memberships cannot be changed through the app (service_role only)
create policy "service_role_manage_boards" on public.boards
  using (auth.role() = 'service_role');

create policy "service_role_manage_board_members" on public.board_members
  using (auth.role() = 'service_role');

-- R7: Anonymous visitors cannot see or change anything
create policy "anon_no_access" on public.boards
  using (false);

create policy "anon_no_access_members" on public.board_members
  using (false);

create policy "anon_no_access_cards" on public.cards
  using (false);

-- R1: Members can see the boards they belong to and every member of those boards
create policy "members_view_boards" on public.boards
  using (
    exists (
      select 1 from public.board_members bm
      where bm.board_id = id
        and bm.user_id = auth.uid()
    )
    or exists (
      select 1 from public.board_members bm2
      where bm2.board_id = id
        and bm2.user_id = auth.uid()
    )
  );

-- ---------------------------------------------------------
-- POLICIES: board_members
-- ---------------------------------------------------------

-- R6: Boards and memberships cannot be changed through the app (service_role only)
create policy "service_role_manage_board_members2" on public.board_members
  using (auth.role() = 'service_role')
  with check (auth.role() = 'service_role');

-- ---------------------------------------------------------
-- POLICIES: cards
-- ---------------------------------------------------------

-- Helper function to check if user is an editor (or service_role) on a board
create or replace function public.is_board_editor(board_id_param bigint, user_id_param uuid)
returns boolean language sql stable security invoker as $$
begin
  if auth.role() = 'service_role' then
    return true;
  end if;
  return exists (
    select 1 from public.board_members bm
    where bm.board_id = board_id_param
      and bm.user_id = user_id_param
      and bm.role = 'editor'
  );
end;
$$;

-- R2: Members can read all cards on their boards
create policy "members_read_cards" on public.cards
  using (
    exists (
      select 1 from public.board_members bm
      where bm.board_id = board_id
        and bm.user_id = auth.uid()
    )
  );

-- R3: Editors can create, edit, move between columns and delete cards on their boards.
--      A card can only end up on a board where the user is an editor.
create policy "editors_manage_cards" on public.cards
  using (
    is_board_editor(board_id, auth.uid())
  )
  with check (
    is_board_editor(board_id, auth.uid())
    and column_name in ('todo', 'doing', 'done')
  );

-- R4: Viewers cannot create, change or delete cards.
--      This is enforced by the editors_manage_cards policy excluding viewers,
--      and the members_read_cards policy only allowing read access.

-- R5: Archived boards are read-only: nobody can create, change or delete cards on an archived board
create policy "archived_boards_read_only" on public.cards
  using (
    not exists (
      select 1 from public.boards b
      where b.id = board_id
        and b.is_archived = true
    )
  )
  with check (
    not exists (
      select 1 from public.boards b
      where b.id = board_id
        and b.is_archived = true
    )
  );
