-- Enable Row Level Security on all relevant tables
alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

-- Grant service_role full access to bypass RLS
grant all on public.boards to service_role;
grant all on public.board_members to service_role;
grant all on public.cards to service_role;

-- RLS Policies for boards
create policy "Boards are viewable by members and archived status is visible"
  on public.boards for select
  using (
    -- Allow viewing boards where user is a member
    exists (
      select 1 from public.board_members
      where board_id = id
      and user_id = auth.uid()
    )
    or
    -- Allow viewing non-archived boards by any authenticated user (public visibility)
    (not is_archived)
  );

create policy "Boards and memberships are immutable by members"
  on public.boards for all
  using (false)
  with check (false);

create policy "Memberships are immutable by members"
  on public.board_members for all
  using (false)
  with check (false);

-- RLS Policies for cards
-- Viewers can read cards on boards they are members of (including archived boards for reading)
create policy "Cards are readable by members"
  on public.cards for select
  using (
    exists (
      select 1 from public.board_members
      where board_id = board_id
      and user_id = auth.uid()
    )
  );

-- Editors can create, update, and delete cards
create policy "Editors can manage cards on their boards"
  on public.cards for all
  using (
    -- User must be an editor on the board
    exists (
      select 1 from public.board_members
      where board_id = board_id
      and user_id = auth.uid()
      and role = 'editor'
    )
    and
    -- Board must not be archived
    not exists (
      select 1 from public.boards
      where id = board_id
      and is_archived = true
    )
  )
  with check (
    -- Same conditions for insert/update/delete
    exists (
      select 1 from public.board_members
      where board_id = board_id
      and user_id = auth.uid()
      and role = 'editor'
    )
    and
    not exists (
      select 1 from public.boards
      where id = board_id
      and is_archived = true
    )
  );

-- Policy to enforce that a card's assignee must be a member of the board (R3)
-- This is enforced via a check constraint on insert/update, but we add a policy for clarity
create policy "Card assignee must be a board member"
  on public.cards (insert, update)
  with check (
    -- The assignee must be a member of the board with at least viewer role
    exists (
      select 1 from public.board_members
      where board_id = board_id
      and user_id = assignee_id
    )
  );
