-- Enable Row Level Security on both tables
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

-- Friendship policies
create policy "Users can view friendships they are part of" on public.friendships
  for select using (
    auth.role() = 'authenticated' and
    (
      (requester_id = auth.uid()) or
      (addressee_id = auth.uid())
    )
  );

create policy "Requesters can insert friend requests" on public.friendships
  for insert with check (
    auth.role() = 'authenticated' and
    requester_id = auth.uid() and
    addressee_id != auth.uid() and
    status = 'pending'
  );

create policy "Addressees can accept pending requests" on public.friendships
  for update using (
    auth.role() = 'authenticated' and
    addressee_id = auth.uid() and
    status = 'pending'
  ) with check (
    status = 'accepted'
  );

create policy "Either party can delete friendship/request" on public.friendships
  for delete using (
    auth.role() = 'authenticated' and
    (
      (requester_id = auth.uid()) or
      (addressee_id = auth.uid())
    )
  );

-- Post policies
create policy "Public and friends can read posts" on public.posts
  for select using (
    auth.role() = 'anon' and audience = 'public' or
    auth.role() = 'authenticated' and (
      author_id = auth.uid() or
      audience = 'public' or
      (
        audience = 'friends' and
        exists (
          select 1 from public.friendships
          where
            (
              (requester_id = auth.uid() and addressee_id = author_id) or
              (addressee_id = auth.uid() and requester_id = author_id)
            ) and status = 'accepted'
        )
      )
    )
  );

create policy "Users can manage own posts" on public.posts
  for all using (author_id = auth.uid()) with check (author_id = auth.uid());

-- Grant service role full access
grant all on public.friendships to service_role;
grant all on public.posts to service_role;
