-- Enable RLS on tables
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

-- ===== Posts RLS =====

-- Policy: Everyone can read public posts
create policy "Public can read public posts"
on public.posts for select
using (audience = 'public');

-- Policy: Authenticated users can read friends-only posts if they are friends
create policy "Friends can read friends-only posts"
on public.posts for select
using (
  audience = 'friends'
  and exists (
    select 1 from public.friendships
    where (
      (requester_id = auth.uid() and addressee_id = author_id)
      or (addressee_id = auth.uid() and requester_id = author_id)
    )
    and status = 'accepted'
  )
);

-- Policy: Users can read their own posts
create policy "Users can read own posts"
on public.posts for select
using (author_id = auth.uid());

-- Policy: Users can insert their own posts (author_id defaults to auth.uid())
create policy "Users can insert own posts"
on public.posts for insert
with check (author_id = auth.uid());

-- Policy: Users can update only their own posts
create policy "Users can update own posts"
on public.posts for update
using (author_id = auth.uid())
with check (author_id = auth.uid());

-- Policy: Users can delete only their own posts
create policy "Users can delete own posts"
on public.posts for delete
using (author_id = auth.uid());

-- ===== Friendships RLS =====

-- Policy: Authenticated users can read friendships they are part of
create policy "Users can read own friendships"
on public.friendships for select
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

-- Policy: Authenticated users can insert friend requests (as requester)
create policy "Users can send friend requests"
on public.friendships for insert
with check (requester_id = auth.uid());

-- Policy: Addressee can accept a pending friend request
create policy "Addressee can accept friend request"
on public.friendships for update
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

-- Policy: Requester or addressee can delete/cancel/decline a friendship
create policy "Users can delete friendships/requests"
on public.friendships for delete
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);
