-- Enable row level security
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

-- Helper function: check if current user is a member of the given org
create function public.is_org_member(org_id bigint) returns boolean language sql as $$
  select exists (
    select 1 from public.org_members
    where org_id = is_org_member.org_id
      and user_id = auth.uid()
  );
$$;

-- Helper function: check if current user is admin of the given org
create function public.is_org_admin(org_id bigint) returns boolean language sql as $$
  select exists (
    select 1 from public.org_members
    where org_id = is_org_admin.org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$;

-- Helper function: check SSO session via amr claim
create function public.is_sso_session() returns boolean language sql as $$
  select exists (
    select 1 from jsonb_to_recordset(coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb, "columns": "amr jsonb") as amr_entry jsonb
    where (amr_entry->>'method')::text = 'sso/saml'
  );
$$;

-- Policy R5: Anonymous visitors cannot see or change anything
-- (implicitly handled by requiring auth for all operations below)

-- Policy R1: Members can see their organizations, members and documents
-- For orgs with require_sso, only SSO sessions can see them
create policy "R1_orgs_select" on public.orgs
  for select using (
    (require_sso = false and is_org_member(org_id)) 
    or (require_sso = true and is_org_member(org_id) and is_sso_session())
  );

create policy "R1_org_members_select" on public.org_members
  for select using (is_org_member(org_id));

create policy "R1_org_documents_select" on public.org_documents
  for select using (
    is_org_member(org_id)
    and (not require_sso or (require_sso and is_sso_session()))
  );

-- Policy R2: Organization admins can CRUD their organization's documents
create policy "R2_org_documents_insert" on public.org_documents
  for insert with check (is_org_admin(org_id) and (not require_sso or is_sso_session()));

create policy "R2_org_documents_update" on public.org_documents
  for update using (is_org_admin(org_id) and (not require_sso or is_sso_session()));

create policy "R2_org_documents_delete" on public.org_documents
  for delete using (is_org_admin(org_id) and (not require_sso or is_sso_session()));

-- Policy R3: Organization admins can change their organization's settings
create policy "R3_orgs_update" on public.orgs
  for update using (is_org_admin(org_id) and (not require_sso or is_sso_session()));

-- Policy R4: Only amr claim counts as proof of SSO; memberships cannot be changed
-- No insert/update/delete policies on org_members beyond what is defined.
-- The existing primary key and check constraints enforce that nobody can change memberships
-- through the app since no RUD policies are created for org_members.

-- Policy R6: Server-side code using the service role keeps full access
-- (service_role bypasses RLS automatically, no additional policy needed)
