-- Enable Row Level Security
alter table public.orgs enable row level security;
alter table public.org_members enable row level security;
alter table public.org_documents enable row level security;

-- Helper function: check if current user is a member of the given org
create function public.is_org_member(org_id bigint) returns boolean language sql as $$
  select exists (
    select 1 from public.org_members
    where org_id = is_org_member.org_id
      and user_id = auth.uid()
  );
$$;

-- Helper function: check if current user is admin of the given org
create function public.is_org_admin(org_id bigint) returns boolean language sql as $$
  select exists (
    select 1 from public.org_members
    where org_id = is_org_admin.org_id
      and user_id = auth.uid()
      and role = 'admin'
  );
$$;

-- Helper function: check SSO session via amr claim
create function public.is_sso_session() returns boolean language plpgsql as $$
begin
  return exists (
    select 1 from jsonb_to_recordset(coalesce(current_setting('request.jwt.claims', true), '{}')::jsonb) as j("amr" jsonb)
    where exists (select 1 from jsonb_array_elements_text(j.amr) as item where item->>'method' = 'sso/saml')
  );
end;
$$;

-- Orgs policies
create policy "orgs_select_policy" on public.orgs
  for select using (
    not exists (
      select 1 from public.org_members
      where org_id = orgs.id
        and user_id = auth.uid()
    ) -- anon can see if member (none) -> actually anon blocked below
    or is_sso_session()
  );

-- Actually enforce anon blocked + SSO for require_sso
create policy "orgs_select_anon_and_sso" on public.orgs
  for select using (
    auth.role() = 'authenticated'
    and (
      not exists (
        select 1 from public.org_members
        where org_id = orgs.id
          and user_id = auth.uid()
      )
      or is_sso_session()
    )
  );

-- Override for require_sso orgs: only SSO sessions can see
create policy "orgs_require_sso" on public.orgs
  for select using (
    require_sso = false
    or is_sso_session()
  );

-- Org members policies (anon blocked, members see their org's members)
create policy "org_members_select" on public.org_members
  for select using (
    auth.role() = 'authenticated'
    and user_id = auth.uid()
  );

-- Org documents policies
create policy "org_documents_select" on public.org_documents
  for select using (
    auth.role() = 'authenticated'
    and (
      exists (
        select 1 from public.org_members
        where org_id = org_documents.org_id
          and user_id = auth.uid()
      )
      or is_sso_session()
    )
  );

-- Admin write policies for documents
create policy "org_documents_admin_write" on public.org_documents
  for all using (
    auth.role() = 'authenticated'
    and is_org_admin(org_documents.org_id)
    and (
      require_sso = false
      or is_sso_session()
    )
  );

-- Admin write policies for org settings (we treat orgs update as admin write via a trigger or separate policy; here we add a policy for updates)
create policy "orgs_admin_update" on public.orgs
  for update using (
    auth.role() = 'authenticated'
    and is_org_admin(orgs.id)
    and (
      require_sso = false
      or is_sso_session()
    )
  );

-- Revoke public access, ensure anon cannot select
revoke all on public.orgs from public;
revoke all on public.org_members from public;
revoke all on public.org_documents from public;

-- Grant to authenticated role (session-aware)
grant select on public.orgs to authenticated;
grant select on public.org_members to authenticated;
grant select, insert, update, delete on public.org_documents to authenticated;

-- Service role keeps full access (already implied but explicit)
grant all on public.orgs to service_role;
grant all on public.org_members to service_role;
grant all on public.org_documents to service_role;
