begin
  if (TG_OP = 'DELETE') then
    -- Allow user to delete their own vote
    if (auth.role() = 'authenticated' and new.user_id = auth.uid()) then
      return new;
    end if;
    return null;
  elsif (TG_OP = 'INSERT') then
    -- Allow insert only if user is signed in, item not shipped, and no existing vote
    if (auth.role() != 'authenticated') then
