  for select using (
    auth.role() = 'authenticated' and (
      bidder_id = auth.uid() 
      or exists (select 1 from public.auctions where id = auction_id and seller_id = auth.uid())
    )
  );

-- Policy: Nobody can modify auctions or bids directly (R2)
create policy "no direct dml on auctions" on public.auctions
  for all using (false);

create policy "no direct dml on bids" on public.bids
  for all using (false);

-- RLS policy for place_bid RPC: only signed-in users can execute (R5, R6 handled by service_role context)
create policy "only signed-in users can place bids" on public.bids
  for insert with check (auth.role() = 'authenticated');

-- Create the place_bid function (R3, R4)
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric language plpgsql security definer as $$
declare
  v_starting_price numeric(10,2);
  v_highest_bid numeric(10,2);
  v_min_increment numeric(10,2);
  v_ends_at timestamptz;
  v_seller_id uuid;
  v_current_highest numeric(10,2);
  v_current_bidder uuid;
begin
  -- R4: caller must be signed in
  if auth.role() != 'authenticated' then
    raise exception 'User must be signed in to place a bid';
  end if;

  -- R4: auction must exist
  select starting_price, min_increment, ends_at, seller_id, highest_bid, highest_bidder
    into v_starting_price, v_min_increment, v_ends_at, v_seller_id, v_current_highest, v_current_bidder
  from public.auctions where id = p_auction_id;

  if not found then
    raise exception 'Auction does not exist';
  end if;

  -- R4: auction must not have ended
  if now() >= v_ends_at then
    raise exception 'Auction has ended';
  end if;

  -- R4: caller must not be the seller
  if auth.uid() = v_seller_id then
    raise exception 'Seller cannot bid on their own auction';
  end if;

  -- R4: validate bid amount
  if v_current_highest is null then
    -- No bids yet: must be at least starting price
    if p_amount < v_starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
  else
    -- Bids exist: must be at least highest bid + minimum increment
    if p_amount < v_current_highest + v_min_increment then
      raise exception 'Bid must be at least highest bid plus minimum increment';
    end if;
  end if;

  -- R3: record the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
    values (p_auction_id, auth.uid(), p_amount, now());

  -- Update auction's highest bid and highest bidder
  update public.auctions
    set highest_bid = p_amount,
        highest_bidder = auth.uid()
  where id = p_auction_id;

  return p_amount;
end;
$$;

