  for select using ( true );

create policy "R2-auctions-no-dml" on public.auctions
  for all using ( false );

-- RLS policies for bids
create policy "R1-bids-select" on public.bids
  for select using (
    auth.role() = 'authenticated' and
    (
      auction_id in (
        select id from public.auctions where seller_id = auth.uid()
      ) or
      bidder_id = auth.uid()
    )
  );

create policy "R2-bids-no-dml" on public.bids
  for all using ( false );

-- Helper function to check auction eligibility
create or replace function public.check_auction_eligibility(
  p_auction_id bigint,
  p_bidder_id uuid,
  p_amount numeric
) returns boolean language sql immutable as $$
begin
  -- auction must exist and not be ended
  if not exists (
    select 1 from public.auctions
    where id = p_auction_id
      and ends_at > now()
  ) then
    return false;
  end if;

  -- bidder must not be the seller
  if exists (
    select 1 from public.auctions
    where id = p_auction_id
      and seller_id = p_bidder_id
  ) then
    return false;
  end if;

  -- amount must be valid
  -- get current highest bid and min increment
  declare
    current_highest numeric(10,2);
    current_min_increment numeric(10,2);
  begin
    select coalesce(highest_bid, starting_price), min_increment
    into current_highest, current_min_increment
    from public.auctions
    where id = p_auction_id;

    if p_bidder_id is null then
      return false;
    end if;

    if p_amount < current_highest then
      if current_highest is null or p_amount < starting_price then
        -- no bids yet, check starting price
        -- we need starting_price from the auction row
        if p_amount < (select starting_price from public.auctions where id = p_auction_id) then
          return false;
        end if;
      end if;
    elsif p_amount < current_highest + current_min_increment then
      return false;
    end if;
  end;

  return true;
end;
$$;

-- RPC function to place a bid
create or replace function public.place_bid(
  p_auction_id bigint,
  p_amount numeric
) returns numeric language sql security invoker as $$
declare
  v_bidder_id uuid;
  v_current_highest numeric(10,2);
  v_current_min_increment numeric(10,2);
  v_starting_price numeric(10,2);
  v_new_highest numeric(10,2);
begin
  -- caller must be signed in
  if auth.role() != 'authenticated' then
    raise exception 'User must be signed in to place a bid';
  end if;

  v_bidder_id := auth.uid();

  -- validate auction eligibility
  if not public.check_auction_eligibility(p_auction_id, v_bidder_id, p_amount) then
    raise exception 'Bid not allowed: auction ended, you are the seller, or amount too low';
  end if;

  -- determine new highest bid
  select coalesce(highest_bid, starting_price), min_increment, starting_price
  into v_current_highest, v_current_min_increment, v_starting_price
  from public.auctions
  where id = p_auction_id;

  if v_current_highest is null or p_amount > v_current_highest then
    v_new_highest := p_amount;
  else
    v_new_highest := v_current_highest;
  end if;

  -- insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder_id, p_amount, now());

  -- update auction highest bid and bidder
  update public.auctions
  set highest_bid = v_new_highest,
      highest_bidder = v_bidder_id
  where id = p_auction_id;

  return v_new_highest;
end;
$$;

-- Grant access for authenticated users
grant usage on schema public to authenticated;
grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant execute on function public.place_bid to authenticated;
grant execute on function public.check_auction_eligibility to authenticated;

-- Service role keeps full access
grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant all on function public.place_bid to service_role;
grant all on function public.check_auction_eligibility to service_role;
