  v_current_highest numeric(10,2);
  v_current_bidder uuid;
begin
  -- R4: caller must be signed in
  if v_bidder is null then
    raise exception 'User must be signed in to place a bid';
  end if;

  -- R4: auction must exist
  select * into v_auction from public.auctions where id = p_auction_id;
  if not found then
    raise exception 'Auction does not exist';
  end if;

  -- R4: caller cannot be the seller
  if v_auction.seller_id = v_bidder then
    raise exception 'Seller cannot bid on their own auction';
  end if;

  -- R4: auction must not have ended
  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- Determine starting price and minimum increment
  v_starting := v_auction.starting_price;
  v_min_inc := coalesce(v_auction.min_increment, 10);

  -- Get current highest bid state
  select highest_bid, highest_bidder into v_current_highest, v_current_bidder
  from public.auctions where id = p_auction_id;

  -- R4: validate bid amount
  if v_current_highest is null then
    -- No bids yet: must be at least starting price
    if p_amount < v_starting then
      raise exception 'Bid must be at least the starting price';
    end if;
  else
    -- Bids exist: must be above highest bid + minimum increment
    if p_amount <= v_current_highest + v_min_inc then
      raise exception 'Bid must be higher than current highest bid by at least the minimum increment';
    end if;
  end if;

  -- R3: record the bid and update the auction's highest bid/highest bidder
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder, p_amount, now());

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_bidder
  where id = p_auction_id;

  return p_amount;
end;
$$;

